def soln(A):
	freq = {}
	for i in A:
		if i in freq.keys():
			freq[i] += 1
		else:
			freq[i] = 1
	A = [*freq.keys()]
	A.sort()
	max_count = sum((freq[x] for x in freq if freq[x] > 1))
	for x in range(1, A[-1] - A[0] + 1):
		(s, p, count) = ([], {}, 0)
		for i in A:
			if i - x in freq:
				p[i] = p[i - x]
			else:
				p[i] = len(s)
				s.append([])
			s[p[i]].append(freq[i])
		for v in s:
			count += sum(v)
			v.sort()
			if len(v) & 1 and v[-1] == 1:
				count -= 1
		max_count = max(max_count, count)
	return max_count
for _ in range(int(input())):
	n = int(input())
	A = list(map(int, input().split()))
	print(soln(A))
